mapper.select:
SELECT r.id AS reservationId, r.source_document_item_id AS orderItemId, i.product_name_snapshot AS productName, i.spec_name_snapshot AS skuName, w.name AS warehouseName, r.unit_snapshot AS unit, r.quantity, r.status, r.occurred_at AS occurredAt FROM xsy_inventory_reservation r JOIN xsy_sales_order_item i ON i.id = r.source_document_item_id AND i.deleted = FALSE LEFT JOIN xsy_warehouse w ON w.id = r.warehouse_id AND w.deleted = FALSE WHERE r.deleted = FALSE AND r.source_document_type = 'SALES_ORDER_ITEM' AND r.source_document_id = #{orderId} AND i.order_id = #{orderId}
AND r.warehouse_id IN #{id}
AND FALSE
ORDER BY i.sort_order, r.id

SELECT t.id AS taskId, t.task_no AS taskNo, t.status AS taskStatus, i.sales_order_item_id AS orderItemId, i.product_name_snapshot AS productName, i.spec_name_snapshot AS skuName, i.sale_unit_snapshot AS unit, i.planned_quantity_snapshot AS plannedQuantity, i.sorted_quantity AS sortedQuantity, i.result, i.sorted_at AS sortedAt FROM xsy_sorting_task_item i JOIN xsy_sorting_task t ON t.id = i.task_id AND t.deleted = FALSE WHERE i.deleted = FALSE AND i.occupation_status = 'ACTIVE' AND t.status != 'CANCELLED' AND i.sales_order_id = #{orderId} AND t.assignee_employee_id = #{employeeId}
AND t.warehouse_id IN #{id}
AND FALSE
ORDER BY t.id, i.id

SELECT r.id AS routeId, r.route_no AS routeNo, r.status AS routeStatus, ro.fulfillment_status AS fulfillmentStatus, r.warehouse_name_snapshot AS warehouseName, r.dispatched_at AS dispatchedAt, ro.signed_at AS signedAt, ro.sign_reason AS signReason FROM xsy_delivery_route_order ro JOIN xsy_delivery_route r ON r.id = ro.route_id AND r.deleted = FALSE WHERE ro.deleted = FALSE AND ro.assignment_status = 'ACTIVE' AND ro.order_id = #{orderId}
AND r.driver_id IN #{id}
AND FALSE
ORDER BY ro.id DESC LIMIT 1
